or.script1:
function check() {
    var term = workflowData.getMetaDataMap().get("Term").toString();
    var career = workflowData.getMetaDataMap().get("Career").toString();
    log.info("term = " + term);
	log.info("career = " + career);
    if (term != "Winter" && term != "Summer" && career != "Self Support - EXED") {
        return true;
    } else {
        return false;
    }
}

or.script2:
function check() {
    var term = workflowData.getMetaDataMap().get("Term").toString();
    var career = workflowData.getMetaDataMap().get("Career").toString();
    log.info("term = " + term);
	log.info("career = " + career);
    if (term == "Winter" || term == "Summer" || career == "Self Support - EXED") {
        return true;
    } else {
        return false;
    }
}
